                    context.table_name,
                )
                await precompute_database_action_permissions(
                    datasette, context.request.actor, context.database_name
                )
            for hook in method(**kwargs):
                extra_links = await await_me_maybe(hook)
                if extra_links:
                    links.extend(extra_links)
            return links

        return actions


